// coupled-subsystem simulation sketch for: MATLAB System Identification Toolbox
const subs = [
  {name:'power', x:0.719, k:0.17},
  {name:'thermal', x:0.497, k:0.182},
  {name:'structural', x:0.899, k:0.117},
  {name:'control', x:0.491, k:0.15},
  {name:'comms', x:0.639, k:0.116},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'MATLAB System Identification Toolbox'}));

